INSERT INTO category (name) VALUES ('Puppy') ON CONFLICT (name) DO NOTHING;
INSERT INTO product (name,price,description,image_file,tag,category_id) SELECT 'Puppy Chicken Recipe',24.90,'Complete dry food for growing puppies.','','puppy,chicken',id FROM category WHERE name='Puppy' AND NOT EXISTS (SELECT 1 FROM product WHERE name='Puppy Chicken Recipe');
